import{_ as n,o as e,c as r,ag as s,j as o}from"./chunks/framework.KxDd3USm.js";const y=JSON.parse('{"title":"04.3 UML 结构图：类图、对象图与用例图 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"04-面向对象与设计模式/03-UML结构图.md","filePath":"04-面向对象与设计模式/03-UML结构图.md"}'),d={name:"04-面向对象与设计模式/03-UML结构图.md"},a={class:"fig"},g={"data-figure-id":"figure-19",viewBox:"0 0 760 300",width:"100%",style:{"max-width":"760px"},role:"img","aria-label":"图书借阅类图。读者、借阅记录和图书都是三格类。一个读者可对应零到多条借阅记录，但每条借阅记录恰好属于一个读者；一本图书也可对应零到多条借阅记录，但每条借阅记录恰好关联一本图书。"},l={class:"fig"},c={"data-figure-id":"figure-20",viewBox:"0 0 760 315",width:"100%",style:{"max-width":"760px"},role:"img","aria-label":"图书馆用例图。系统边界内有借书、登录、查询图书和逾期提示四个用例；读者是边界外参与者。借书和查询图书都通过 include 指向登录，表示登录是必经的共用行为；逾期提示通过 extend 指向借书，表示只有逾期条件满足时才出现的可选分支。"};function x(i,t,p,u,h,q){return e(),r("div",null,[t[4]||(t[4]=s(`<h1 id="_04-3-uml-结构图-类图、对象图与用例图-★★★" tabindex="-1">04.3 UML 结构图：类图、对象图与用例图 ★★★ <a class="header-anchor" href="#_04-3-uml-结构图-类图、对象图与用例图-★★★" aria-label="Permalink to &quot;04.3 UML 结构图：类图、对象图与用例图 ★★★&quot;">​</a></h1><h3 id="_3-0-先建全景-uml-2-x-共-13-种图-按-静态-动态-一刀切开" tabindex="-1">3.0 先建全景：UML 2.x 共 13 种图，按&quot;静态/动态&quot;一刀切开 <a class="header-anchor" href="#_3-0-先建全景-uml-2-x-共-13-种图-按-静态-动态-一刀切开" aria-label="Permalink to &quot;3.0 先建全景：UML 2.x 共 13 种图，按&quot;静态/动态&quot;一刀切开&quot;">​</a></h3><p>UML 2.x 共定义 <strong>13 种图</strong>，按&quot;静态/动态&quot;一刀切开（其中最常见的 10 种必须全认，末尾三种低频，<strong>认名字即可</strong>）：</p><table tabindex="0"><thead><tr><th>类别</th><th>图</th><th>一句话用途</th><th>认图特征</th></tr></thead><tbody><tr><td><strong>静态（结构图）</strong></td><td>类图</td><td>一组对象、接口、协作及其关系</td><td>矩形分三格：类名/属性/操作</td></tr><tr><td></td><td>对象图</td><td>某一时刻的对象快照</td><td>名字带<strong>下划线</strong></td></tr><tr><td></td><td>构件图（组件图）</td><td>一组构件之间的组织和依赖（静态<strong>实现</strong>视图）</td><td>构件符号（带两个小凸起）+ 供/需接口</td></tr><tr><td></td><td>部署图</td><td>运行处理<strong>节点</strong>及构件的配置（静态<strong>实施</strong>视图）</td><td><strong>立体长方体</strong>（节点）</td></tr><tr><td></td><td>包图</td><td>类/图如何组织成包及包间依赖</td><td>文件夹形状</td></tr><tr><td></td><td>组合结构图</td><td>分解类、构件或用例的<strong>内部结构</strong></td><td>大框套小框、内部部件</td></tr><tr><td><strong>动态（行为图）</strong></td><td>用例图</td><td>用例、参与者及其关系</td><td>小人（参与者）+ 椭圆（用例）</td></tr><tr><td></td><td>顺序图（序列图）</td><td>以<strong>时间顺序</strong>组织的对象间交互</td><td>竖直生命线 + 水平消息箭头</td></tr><tr><td></td><td>通信图（协作图）</td><td>强调收发消息的对象的<strong>组织结构</strong></td><td>对象间连线标消息序号</td></tr><tr><td></td><td>状态图</td><td>一个<strong>状态机</strong>：状态、转换、事件、活动</td><td>圆角矩形（状态）+ 箭头（转换）</td></tr><tr><td></td><td>活动图</td><td>一个活动到另一个活动的<strong>流程</strong></td><td>泳道、分叉/汇合粗横线</td></tr><tr><td></td><td>交互概览图</td><td>组合顺序图与活动图的特征，显示对象如何交互</td><td>像活动图但节点是交互引用</td></tr><tr><td></td><td>定时图</td><td>关注对象改变状态时的<strong>时间约束</strong></td><td>时间刻度、状态阶梯</td></tr></tbody></table><p><strong>记忆抓手</strong>：结构图 6 种 = <strong>类、对象、构件、部署、包、组合结构</strong>；行为图 7 种 = <strong>用例、顺序、通信、状态、活动、交互概览、定时</strong>。其中真正高频的是 <strong>10 种（静态五 + 动态五）</strong>——类图、对象图、构件图、部署图、包图、用例图、顺序图、通信图、状态图、活动图。多出的三种（组合结构图、交互概览图、定时图）只会在&quot;UML 图不包括下列哪种&quot;这类题里当干扰项出现。</p><p><strong>反例演示（易错）</strong>：状态图和活动图长得像，区别在——状态图描述<strong>一个对象</strong>因事件引起的状态变迁，必须以&quot;事件&quot;为转换条件；活动图描述<strong>业务流程</strong>步骤，支持并发分支（分叉/汇合），不关心某个对象。另外顺序图 vs 通信图：<strong>内容等价、侧重不同</strong>——顺序图突出时间顺序，通信图突出对象间链接结构，两者可以互相转换（案例题常要求&quot;画出通信图&quot;）。</p><h3 id="_3-1-类图与对象图-三格-可见性-多重性" tabindex="-1">3.1 类图与对象图：三格 + 可见性 + 多重性 <a class="header-anchor" href="#_3-1-类图与对象图-三格-可见性-多重性" aria-label="Permalink to &quot;3.1 类图与对象图：三格 + 可见性 + 多重性&quot;">​</a></h3><p><strong>类图的矩形三格</strong>（从上到下）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────┐</span></span>
<span class="line"><span>│      类名 Book       │  ← 第 1 格：类名（抽象类用斜体）</span></span>
<span class="line"><span>├──────────────────────┤</span></span>
<span class="line"><span>│ - 书号  : String     │  ← 第 2 格：属性    - 私有  + 公有  # 保护</span></span>
<span class="line"><span>│ - 定价  : double     │</span></span>
<span class="line"><span>├──────────────────────┤</span></span>
<span class="line"><span>│ + 借出() : boolean   │  ← 第 3 格：操作（方法）  括号不能省</span></span>
<span class="line"><span>│ + 计算应还日() : Date│</span></span>
<span class="line"><span>└──────────────────────┘</span></span></code></pre></div><p><strong>可见性符号</strong>（选择题直接问 <code>-</code> 是什么意思）：<code>+</code> 公有 public、<code>-</code> 私有 private、<code>#</code> 保护 protected。考场上看到属性前全是一串减号，说明是<strong>私有属性</strong>（这正是封装）。</p><p><strong>多重性（读书数字）vs 基数</strong>：题目常给你一句业务的自然语言，要你翻成符号。<strong>翻法</strong>是&quot;<strong>在每一端，问自己：一个对面对象能对应几个我</strong>&quot;：</p><table tabindex="0"><thead><tr><th>符号</th><th>读作</th><th>业务原话的样子</th></tr></thead><tbody><tr><td><code>1</code></td><td>恰好一个</td><td>&quot;每本书只属于一个书架&quot;</td></tr><tr><td><code>0..1</code></td><td>零个或一个</td><td>&quot;读者可能有一条&quot;欠款记录&quot;，也可能没有&quot;</td></tr><tr><td><code>1..*</code></td><td>一个或多个（<strong>至少一个</strong>）</td><td>&quot;一名读者至少有一条借阅记录&quot;</td></tr><tr><td><code>0..*</code> 或 <code>*</code></td><td>零个或多个（<strong>可以没有</strong>）</td><td>&quot;一个书架可以没有任何图书&quot;</td></tr></tbody></table><p><strong>反例演示（易错）</strong>：<code>1..*</code> 与 <code>0..*</code> 只差一个数字，含义却相反。判断口诀——<strong>看&quot;至少&quot;这个词</strong>：题干出现&quot;至少有/必须有&quot;→ 端点写 <code>1..*</code>；出现&quot;可以没有/可能没有/不一定有&quot;→ 写 <code>0..*</code>。这里最容易把手写答案画反，因为<strong>同一句话的两端各有一个多重性</strong>：如&quot;读者可借多本书&quot;，在<strong>图书端</strong>要写的不是&quot;多&quot;而是&quot;1&quot;（一本书只被一条借阅记录指向一个读者），在<strong>读者端</strong>才写 <code>0..*</code>。<strong>逐端问、别照抄句子</strong>。</p><p><strong>对象图</strong>：类图是&quot;模板&quot;，对象图是&quot;<strong>某一时刻的快照</strong>&quot;。识别特征就是<strong>名字带下划线、冒号前是对象名、冒号后是类名</strong>，写成 <code>:图书</code> 或 <code>b1 : 图书</code>。</p>`,14)),o("figure",a,[(e(),r("svg",g,[...t[0]||(t[0]=[s('<text x="280" y="25" class="h">借阅关系：多重性写在“对面对象的数量”一端</text><rect x="42" y="90" width="180" height="136" class="c"></rect><rect x="42" y="90" width="180" height="38" class="head"></rect><line x1="42" y1="175" x2="222" y2="175" stroke="var(--line)"></line><text x="111" y="115" class="h">读者</text><text x="55" y="151" class="t">- 读者号 : String</text><text x="55" y="169" class="t">- 姓名 : String</text><text x="55" y="202" class="t">+ 借阅() : boolean</text><rect x="290" y="90" width="180" height="136" class="c"></rect><rect x="290" y="90" width="180" height="38" class="head"></rect><line x1="290" y1="175" x2="470" y2="175" stroke="var(--line)"></line><text x="345" y="115" class="h">借阅记录</text><text x="303" y="151" class="t">- 借出日 : Date</text><text x="303" y="169" class="t">- 应还日 : Date</text><text x="303" y="202" class="t">+ 归还()</text><rect x="538" y="90" width="180" height="136" class="c"></rect><rect x="538" y="90" width="180" height="38" class="head"></rect><line x1="538" y1="175" x2="718" y2="175" stroke="var(--line)"></line><text x="609" y="115" class="h">图书</text><text x="551" y="151" class="t">- 书号 : String</text><text x="551" y="169" class="t">- 书名 : String</text><text x="551" y="202" class="t">+ 是否可借() : boolean</text><path d="M222 158H290" class="e"></path><text x="230" y="148" class="t">1</text><text x="257" y="148" class="t">0..*</text><text x="238" y="187" class="s">拥有</text><path d="M470 158H538" class="e"></path><text x="478" y="148" class="t">0..*</text><text x="519" y="148" class="t">1</text><text x="486" y="187" class="s">对应</text><text x="65" y="267" class="s">读法示例：每条借阅记录关联 1 位读者；1 位读者可以没有记录，也可以有多条记录。</text>',31)])])),t[1]||(t[1]=o("figcaption",null,"类图既要看三格，也要逐端读多重性；不能把自然语言里的“多”原样抄到两端。",-1))]),t[5]||(t[5]=s('<h3 id="_3-2-用例图-三个要素-三种关系-建模流程四步-★★" tabindex="-1">3.2 用例图：三个要素 + 三种关系 + 建模流程四步 ★★ <a class="header-anchor" href="#_3-2-用例图-三个要素-三种关系-建模流程四步-★★" aria-label="Permalink to &quot;3.2 用例图：三个要素 + 三种关系 + 建模流程四步 ★★&quot;">​</a></h3><p><strong>要素</strong>：<strong>参与者</strong>（小人，缩写可以是人、外部系统）、<strong>用例</strong>（椭圆，一件完整的、有业务价值的事）、<strong>关系</strong>（连线）。</p><p><strong>三种关系</strong>（选择题 + 案例题双考）：</p><table tabindex="0"><thead><tr><th>关系</th><th>符号</th><th>判据</th><th>例</th></tr></thead><tbody><tr><td><strong>包含</strong> <code>&lt;&lt;include&gt;&gt;</code></td><td>虚线箭头 + 构造型，<strong>基用例 → 被包含用例</strong></td><td><strong>必经</strong>、可被多个用例共用的公共行为</td><td>借书<strong>必须先</strong>登录；借书/还书/查询<strong>都要</strong>检查权限</td></tr><tr><td><strong>扩展</strong> <code>&lt;&lt;extend&gt;&gt;</code></td><td>虚线箭头 + 构造型，<strong>扩展用例 → 基用例</strong></td><td><strong>可选</strong>、条件触发、是基用例的分支场景</td><td>超额时<strong>才</strong>弹逾期提示；勾选定时发布<strong>才</strong>执行</td></tr><tr><td><strong>泛化</strong></td><td>空心三角实线，<strong>子用例 → 父用例</strong></td><td>多个用例有<strong>共同的类似结构和行为</strong>，抽出父用例</td><td>网上注册/电话注册 → 泛化到&quot;课程注册&quot;</td></tr></tbody></table><p><strong>方向易错</strong>：include 是<strong>基用例指出去</strong>（借书 → 登录）；extend 是<strong>扩展用例指回来</strong>（拒绝提示 → 借书）。口诀：<strong>include 从主干指出，extend 从分支指回</strong>；判断只用一句话——<strong>&quot;没有它这事就干不成&quot;是 include，&quot;有它也行没它也行&quot;是 extend</strong>。</p><p><strong>用例建模流程（四步，其中前三步必须、第四步可选）</strong>：</p><ol><li><strong>识别参与者</strong>（必须）—— 谁使用系统、系统服务谁；</li><li><strong>合并需求获得用例</strong>（必须）—— 把每个参与者要做的事收成用例；</li><li><strong>细化用例描述</strong>（必须）—— 写&quot;典型事件流 + 备选事件流&quot;；</li><li><strong>调整用例模型</strong>（可选）—— 抽 include/extend/泛化，简化模型。</li></ol><p><strong>案例题怎么用这四步</strong>：真题给的&quot;用例详细描述&quot;就是第 3 步的产物，<strong>结构固定为——参与者 / 典型事件流（正常步骤 1、2、3…）/ 备选事件流（2a、4a 这类&quot;异常分支&quot;）</strong>。读题时把<strong>典型事件流的步骤</strong>当主线索（对应顺序图的消息顺序），把<strong>编号带字母的备选事件流</strong>当 <strong>extend 的来源</strong>（如&quot;4a 读者要借的书无法外借&quot;→ 扩展用例）。</p><p><strong>反例演示（易错）</strong>：&quot;参与者&quot;里可以有<strong>外部系统</strong>（如&quot;支付网关&quot;&quot;短信平台&quot;），不一定是人；反过来，&quot;系统内部的某个模块&quot;<strong>不能</strong>当参与者——参与者必须<strong>在系统边界之外</strong>。这是选择题的常见陷阱：给你&quot;数据库&quot;&quot;登录模块&quot;当选项，它们都是系统内部的东西，不是参与者。</p>',9)),o("figure",l,[(e(),r("svg",c,[...t[2]||(t[2]=[s('<defs><marker id="uml-open" markerWidth="9" markerHeight="9" refX="8" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="none" stroke="var(--ink)" stroke-width="1.5"></path></marker></defs><rect x="206" y="28" width="505" height="250" rx="8" class="bound"></rect><text x="226" y="54" class="h">图书馆系统</text><circle cx="83" cy="91" r="13" class="e"></circle><path d="M83 104V154M58 120H108M83 154L58 187M83 154L108 187" class="e"></path><text x="62" y="210" class="t">读者</text><ellipse cx="360" cy="112" rx="66" ry="28" class="uc"></ellipse><text x="339" y="117" class="t">借书</text><ellipse cx="555" cy="112" rx="66" ry="28" class="uc"></ellipse><text x="519" y="117" class="t">登录</text><ellipse cx="360" cy="207" rx="66" ry="28" class="uc"></ellipse><text x="318" y="212" class="t">查询图书</text><ellipse cx="555" cy="207" rx="66" ry="28" class="uc"></ellipse><text x="520" y="212" class="t">逾期提示</text><path d="M108 128H293" class="e"></path><path d="M108 158L293 201" class="e"></path><path d="M426 112H488" class="d" marker-end="url(#uml-open)"></path><text x="431" y="100" class="s">include（必经）</text><path d="M426 207L507 130" class="d" marker-end="url(#uml-open)"></path><text x="427" y="188" class="s">include（必经）</text><path d="M498 186Q458 162 421 132" class="d" marker-end="url(#uml-open)"></path><text x="452" y="157" class="s">extend [逾期]</text><text x="223" y="301" class="s">方向口诀：主干指向被包含用例；可选分支指回基用例。</text>',23)])])),t[3]||(t[3]=o("figcaption",null,"用例图先划系统边界：读者在边界外；`include` 与 `extend` 的箭头方向相反。",-1))])])}const b=n(d,[["render",x]]);export{y as __pageData,b as default};
